export const BODY: string = "\n<p>تصویر ایک لمحہ دکھاتی ہے۔ اس کا EXIF ڈیٹا اس لمحے کے گرد کہانی بتاتا ہے: کس کیمرے نے لی، کب، کہاں، اور کن سیٹنگ سے۔</p>\n<p>زیادہ تر لوگ یہ تہہ کبھی نہیں دیکھتے۔ یہ فائل کے اندر خاموشی سے سفر کرتی ہے، کاپی، فارورڈ، اور ڈاؤن لوڈ سے بچتی ہے جب تک کچھ اسے ہٹا نہ دے۔</p>\n<p>یہ مضمون EXIF کو گہرائی سے بتاتا ہے: یہ کیسے بنا ہے، ہر فیلڈ کیا ظاہر کرتی ہے، یہ کیسے لیک ہوتا ہے، اور اسے کیسے پڑھیں اور ہٹائیں۔ بھرتی نہیں، صرف وہ جو ڈیٹا کہتا ہے۔</p>\n<h2 id=\"what-is-exif\">EXIF اصل میں کیا ہے</h2>\n<p>EXIF کا مطلب Exchangeable Image File Format ہے۔ یہ تصویر فائلوں کے اندر میٹا ڈیٹا محفوظ کرنے کا معیار ہے، جو کیمرے اور فون پکڑنے کے لمحے لکھتے ہیں۔</p>\n<p>تکنیکی طور پر EXIF ڈیٹا فائل میں سرایت شدہ TIFF پر مبنی ساخت میں رہتا ہے۔ JPEG میں یہ APP1 سیگمنٹ میں بیٹھتا ہے؛ PNG میں یہ eXIf چنک میں بیٹھ سکتا ہے؛ WebP میں یہ بھی سرایت شدہ ہوتا ہے۔</p>\n<p>ساخت ڈائریکٹریوں کا سیٹ ہے جنہیں IFD کہتے ہیں، Image File Directories کا مخفف۔ ہر IFD نمبر والے ٹیگ رکھتی ہے، اور ہر ٹیگ قدر رکھتا ہے: نمبر، سٹرنگ، یا کسر۔</p>\n<p>ویور JPEG فائلوں میں تین IFD پڑھتا ہے: بنیادی آلہ حقائق کے لیے IFD0، ایکسپوژر ٹیلی میٹری کے لیے ExifIFD، اور مقام کے لیے GPSIFD۔ تقریباً سب کچھ وہیں ہے۔</p>\n<p>EXIF تصویر میں واحد میٹا ڈیٹا نہیں ہے۔ XMP پیکٹ، IPTC فیلڈ، JPEG تبصرے، اور PNG متن چنک اس کے ساتھ بیٹھ سکتے ہیں، مگر EXIF سب سے بھرپور اور سب سے معیاری ہے۔</p>\n<h2 id=\"ifd0-device-identity\">IFD0: آپ کے آلے کی شناخت</h2>\n<p>IFD0 پہلی ڈائریکٹری ہے، اور یہ آلے کی شناخت کرتی ہے۔ کیمرہ بنانے والا اور ماڈل سرخی فیلڈ ہیں، مگر اس سے زیادہ بھی ہے۔</p>\n<p>سافٹ ویئر فیلڈ وہ پروگرام ریکارڈ کرتی ہے جس نے فائل کو آخری بار لکھا۔ یہ کیمرہ فرم ویئر ورژن، فون آپریٹنگ سسٹم، یا Lightroom جیسی ایڈیٹنگ ایپ ہو سکتی ہے۔</p>\n<p>کچھ کیمرے یہاں سیریل نمبر یا مالک کا نام ریکارڈ کرتے ہیں۔ وہ فیلڈ گمنام تصویر کو ایک مخصوص آلے سے اور کبھی ایک مخصوص شخص سے جوڑی ہوئی تصویر میں بدل دیتی ہیں۔</p>\n<p>آرٹسٹ فیلڈ فوٹوگرافر کا نام رکھ سکتی ہے، اور کاپی رائٹ فیلڈ حقوق کا نوٹس رکھ سکتی ہے۔ دونوں پیشہ ور افراد کے لیے جائز ہیں، اور دونوں شناخت کرنے والی ہیں۔</p>\n<p>تصویر ابعاد اور اورینٹیشن جھنڈا بھی یہیں رہتے ہیں۔ اورینٹیشن ٹیگ ہی ویور کو بتاتا ہے کہ تصویر کو سیدھا گھمائیں، اور یہی وہ فیلڈ ہے جو اکثر الٹی تصویر کا سبب بنتی ہے۔</p>\n<h2 id=\"exififd-exposure-telemetry\">ExifIFD: ایکسپوژر ٹیلی میٹری</h2>\n<p>ExifIFD EXIF کا تکنیکی دل ہے۔ یہ ایکسپوژر فیصلے ریکارڈ کرتا ہے جو کیمرے نے کیے، یا آپ نے کیے، پکڑنے کے لمحے۔</p>\n<p>ISO، اپرچر، شٹر رفتار، اور فوکل لمبائی وہ چار فیلڈ ہیں جن کی فوٹوگرافر سب سے زیادہ پرواہ کرتے ہیں۔ ساتھ مل کر وہ روشنی، فیلڈ کی گہرائی، اور حرکت کو بیان کرتے ہیں۔</p>\n<p>ایکسپوژر وقت عقلی کسر کے طور پر محفوظ ہوتا ہے، جیسے سیکنڈ کا 1/250۔ اپرچر F-نمبر کے طور پر محفوظ ہوتا ہے۔ فوکل لمبائی ملی میٹر میں محفوظ ہوتی ہے، کبھی 35 ملی میٹر مساوی کے ساتھ۔</p>\n<p>فلیش حالت ریکارڈ کرتی ہے کہ فلیش چلا یا نہیں، اور کس موڈ میں۔ میٹرنگ موڈ ریکارڈ کرتا ہے کہ کیمرے نے منظر کیسے ناپا: اوسط، مرکز وزنی، اسپاٹ، یا کثیر۔</p>\n<p>وائٹ بیلنس، ایکسپوژر پروگرام، اور ایکسپوژر معاوضہ مزید تفصیل بڑھاتے ہیں۔ تربیت یافتہ قاری صرف ان فیلڈ سے شوٹنگ حالات دوبارہ بنا سکتا ہے۔</p>\n<h2 id=\"gpsifd-location\">GPSIFD: مقام ڈائریکٹری</h2>\n<p>GPSIFD سب سے چھوٹی ڈائریکٹری اور سب سے خطرناک ہے۔ یہ عرض بلد، طول بلد، اور اونچائی کو ڈگری، منٹ، اور سیکنڈ میں عقلی نمبروں کے طور پر رکھتی ہے۔</p>\n<p>ویور ان کسروں کو خود بخود اعشاریہ نقاط میں بدلتا ہے۔ 25.2048، 55.2708 جیسا جوڑا نقشے پر درست نقطہ ہے، اتنا درست کہ عمارت کی شناخت ہو سکے۔</p>\n<p>GPS ٹیگ ٹائم اسٹیمپ اور شمال یا جنوب، مشرق یا مغرب کا حوالہ بھی لے کر آتے ہیں۔ تاریخ مہر ریکارڈ کرتی ہے کہ مقام کب طے ہوا، جو عام طور پر پکڑنے کے وقت سے میل کھاتا ہے۔</p>\n<p>اونچائی بھی اکثر موجود ہوتی ہے، اگرچہ یہ افقی نقاط سے کم درست ہوتی ہے۔ فون پر یہ پھر بھی بتا سکتی ہے کہ تصویر زمینی سطح پر لی گئی یا اونچی منزل پر۔</p>\n<p>فون زیادہ تر کیمرہ ایپس میں ڈیفالٹ سے GPS ریکارڈ کرتے ہیں۔ نقاط خاموشی سے لکھے جاتے ہیں، تصویر پر کوئی نظر آنے والا نشان نہیں، اور زیادہ تر مالک کبھی نہیں جانتے کہ وہ وہاں ہیں۔</p>\n<h2 id=\"what-photos-reveal\">آپ کی تصاویر آپ کے بارے میں کیا ظاہر کرتی ہیں</h2>\n<p>ایک تصویر تھوڑا ظاہر کرتی ہے۔ تصاویر کا سیٹ بہت کچھ ظاہر کرتا ہے۔ EXIF تصویر مجموعے کو جگہوں، معمولات، اور آلات کی ٹائم لائن میں بدل دیتا ہے۔</p>\n<p>بہت سی تصاویر میں پکڑنے کے ٹائم اسٹیمپ دکھاتے ہیں کہ آپ کب گھر ہوتے ہیں، کب سفر کرتے ہیں، اور کب عام طور پر دور ہوتے ہیں۔ یہ معمول ہے، اور معمول ان لوگوں کے لیے قیمتی ہوتے ہیں جو اسے استعمال کرنا چاہتے ہیں۔</p>\n<p>بہت سی تصاویر میں GPS نقاط آپ کا گھر، کام کی جگہ، جم، اور بچوں کا اسکول نقشہ بناتے ہیں۔ ناموں کے بغیر بھی نمونہ نقشے پر واضح ہوتا ہے۔</p>\n<p>کیمرہ سیریل نمبر تصاویر کو ایک آلے سے جوڑتے ہیں۔ اگر وہی سیریل مختلف ناموں کے تحت تصاویر میں ظاہر ہو تو ان شناختوں کے درمیان ربط نظر آنے لگتا ہے۔</p>\n<p>سافٹ ویئر فیلڈ آپ کے ایڈیٹنگ ٹول اور آپریٹنگ سسٹم ظاہر کرتی ہیں۔ یہ اکیلے معمولی ہے، مگر ٹائم اسٹیمپ اور مقام کے ساتھ مل کر یہ آپ کی زندگی کی تفصیلی تصویر بڑھاتی ہے۔</p>\n<p>نقطہ یہ نہیں کہ کوئی واحد فیلڈ خفیہ ہے۔ نقطہ یہ ہے کہ فیلڈ مل کر آپ کی زندگی کی ایسی تصویر بناتی ہیں جسے آپ نے شائع کرنے کا کبھی انتخاب نہیں کیا۔</p>\n<h2 id=\"how-exif-survives\">EXIF کیسے بچتا ہے، اور کیسے مرتا ہے</h2>\n<p>EXIF کاپی کرنے، ای میل کرنے، اور فولڈروں کے درمیان فائلیں منتقل کرنے سے بچتا ہے۔ یہ فائل کا حصہ ہے، اس لیے یہ جہاں فائل جاتی ہے وہاں جاتا ہے، جب تک کچھ اسے فعال طور پر نہ ہٹائے۔</p>\n<p>سوشل نیٹ ورک اور میسجنگ ایپس بڑے ہٹانے والے ہیں۔ WhatsApp، Instagram، اور Facebook اپ لوڈ پر EXIF، کیمرہ، اور GPS ہیڈر خود بخود ہٹا دیتے ہیں۔</p>\n<p>اسی لیے Instagram سے ڈاؤن لوڈ شدہ تصویر <a href=\"/ur/tasveer-metadata-dekhein/\">Image Metadata Viewer</a> میں صفر EXIF ٹیگ دکھاتی ہے۔ پلیٹفارم نے اسے صاف کیا، آپ نے نہیں۔</p>\n<p>ایڈیٹنگ ایپس مختلف ہوتی ہیں۔ کچھ ایکسپورٹ پر EXIF رکھتی ہیں، کچھ چھوڑ دیتی ہیں، اور کچھ انتخاب دیتی ہیں۔ ایڈٹ شدہ اور دوبارہ ایکسپورٹ شدہ تصویر اپنا کیمرہ ڈیٹا کھو سکتی ہے جبکہ اس کے پکسل رکھتی ہے۔</p>\n<p>اسکرین شاٹ میں پہلے سے EXIF نہیں ہوتا۔ کلپ بورڈ خام پکسل منتقل کرتا ہے، اس لیے اسکرین شاٹ صرف ابعاد اور فارمیٹ لے کر آتا ہے، بغیر کیمرہ یا GPS بلاک کے۔</p>\n<p>مارکیٹ پلیس، فورم، اور ای میل منسلکات مختلف ہیں۔ ان میں سے بہت سے اصل فائل کو اچھوتا رکھتے ہیں، اس لیے EXIF اور GPS اجنبی کے آلے تک سفر بچاتے ہیں۔</p>\n<h2 id=\"reading-exif\">EXIF ڈیٹا کیسے پڑھیں</h2>\n<p>EXIF پڑھنے کے لیے ویور چاہیے ہوتا ہے، کیونکہ کوئی آپریٹنگ سسٹم ڈیفالٹ سے مکمل تصویر نہیں دکھاتا۔ <a href=\"/ur/tasveer-metadata-dekhein/\">Image Metadata Viewer</a> خام بائٹ کو مقامی طور پر پارس کرتا ہے اور انہیں گروپ کرتا ہے۔</p>\n<p>خلاصہ بینر سے شروع کریں۔ یہ آپ کو فارمیٹ، ابعاد، اور یہ بتاتا ہے کہ حساس ٹیگ اقسام ملیں یا نہیں۔ پھر GPS الرٹ چیک کریں، جو ڈی کوڈ شدہ نقاط دکھاتا ہے۔</p>\n<p>اگلا گروپ شدہ جدول پڑھیں۔ کیمرہ فیلڈ آلے کی شناخت کرتے ہیں، EXIF فیلڈ ایکسپوژر بیان کرتے ہیں، اور GPS فیلڈ مقام دیتے ہیں۔ Amber Privacy Tag لیبل حساس اندراج کو نشان زد کرتے ہیں۔</p>\n<p>جب آپ کو ریکارڈ چاہیے تو JSON ایکسپورٹ کریں۔ Copy JSON مکمل ساختہ رپورٹ آپ کے کلپ بورڈ پر رکھتا ہے، اور Export JSON ایسی فائل ڈاؤن لوڈ کرتا ہے جسے آپ رکھ سکتے ہیں یا بگ رپورٹ سے جوڑ سکتے ہیں۔</p>\n<p>مرحلہ بہ مرحلہ عمل کے لیے <a href=\"/ur/blog/tasveer-metadata-kaise-dekhein/\">How to View Image Metadata</a> پڑھیں۔ مکمل ٹول جائزے کے لیے <a href=\"/ur/blog/tasveer-metadata-viewer-rehnumai/\">Image Metadata Viewer: Complete Guide</a> پڑھیں۔</p>\n<h2 id=\"exif-vs-xmp-iptc\">EXIF بمقابلہ XMP بمقابلہ IPTC</h2>\n<p>EXIF اکیلا نہیں ہے۔ دو دوسرے معیار اکثر فائل شیئر کرتے ہیں، اور ہر ایک مختلف چیزیں ظاہر کرتا ہے۔</p>\n<p>XMP فائل میں سرایت شدہ Adobe XML پیکٹ ہے۔ یہ ایڈیٹنگ تاریخ، درجہ بندی، لیبل، اور تفصیل رکھ سکتا ہے۔ Lightroom یا Photoshop میں ایڈٹ شدہ تصویر میں اکثر بھرپور XMP ہوتا ہے۔</p>\n<p>IPTC پریس اور اشاعت معیار ہے۔ یہ کیپشن، سرخیاں، کلیدی الفاظ، کریڈٹ، اور کاپی رائٹ معلومات رکھتا ہے۔ خبر تصاویر اور اسٹاک تصاویر IPTC سے بھرپور ہوتی ہیں۔</p>\n<p>EXIF کیمرے سے لکھا جاتا ہے۔ XMP ایڈیٹنگ سافٹ ویئر سے لکھا جاتا ہے۔ IPTC لوگوں اور ناشرین سے لکھا جاتا ہے۔ ایک تصویر تینوں لے کر آ سکتی ہے، ہر ایک مختلف کہانی سناتا ہے۔</p>\n<p>صرف EXIF ہٹانا ہمیشہ کافی نہیں ہوتا۔ مکمل صفائی XMP پیکٹ، IPTC فیلڈ، JPEG تبصرے، اور PNG متن چنک بھی ہٹاتی ہے، جو <a href=\"/ur/tasveer-metadata-hatayein/\">Remove Image Metadata</a> ٹول کرتا ہے۔</p>\n<h2 id=\"exif-and-orientation\">EXIF اورینٹیشن: الٹی تصویر کا مسئلہ</h2>\n<p>اورینٹیشن ٹیگ چھوٹی EXIF فیلڈ ہے جس کا اثر بہت بڑا ہے۔ یہ ویور کو بتاتا ہے کہ تصویر کو سیدھا کیسے گھمائیں، کیونکہ کیمرے اکثر پکسل کو ایک سمت میں اور ہدایت کو دوسری میں محفوظ کرتے ہیں۔</p>\n<p>جب ٹیگ پکسل گھمائے بغیر ہٹایا جائے تو عمودی تصویر الٹی ظاہر ہو سکتی ہے۔ تصویر ڈیٹا بدلا نہیں، مگر وہ ہدایت جس نے اسے سیدھا بنایا تھا غائب ہو گئی۔</p>\n<p>اسی لیے Remove Image Metadata ٹول دو طریقے دیتا ہے۔ Lossless Binary Strip APP1 بلاک ہٹاتا ہے، بشمول اورینٹیشن جھنڈا، بغیر پکسل کو چھوئے۔</p>\n<p>Full Canvas Re-encode مختلف راستہ لیتا ہے۔ یہ پکسل کو تازہ کینوس پر کھینچتا ہے، سیدھی اورینٹیشن کو سیدھا ایکسپورٹ شدہ تصویر میں پکاتا ہے، اس لیے تصویر ہمیشہ سیدھی رہتی ہے۔</p>\n<p>اگر عمودی JPEG لاس لیس ہٹانے کے بعد الٹی لگے تو Full Canvas Re-encode پر جائیں اور Re-clean All پر کلک کریں۔ پکسل خود درست ہو جاتے ہیں، اور کوئی میٹا ڈیٹا باقی نہیں رہتا۔</p>\n<h2 id=\"exif-for-photographers\">فوٹوگرافروں اور ڈویلپروں کے لیے EXIF</h2>\n<p>EXIF صرف پرائیویسی خطرہ نہیں ہے۔ فوٹوگرافروں کے لیے یہ سیکھنے کا ٹول ہے، اور ڈویلپروں کے لیے یہ ڈیبگ کرنے کی مدد ہے۔</p>\n<p>فوٹوگرافر بہترین شاٹ کی ایکسپوژر سیٹنگ پڑھ سکتا ہے اور انہیں دہرا سکتا ہے۔ ISO، اپرچر، شٹر رفتار، اور فوکل لمبائی ساتھ مل کر اسی شاٹ کی ترکیب بناتے ہیں۔</p>\n<p>ڈویلپر عجیب رویے کی وضاحت کے لیے EXIF پڑھ سکتا ہے۔ غلط اورینٹیشن جھنڈا، PNG pHYs چنک سے غیر متوقع DPI قدر، یا چھپا ہوا رنگ پروفائل اکثر مسئلہ بتاتے ہیں۔</p>\n<p>دو فائلوں کا موازنہ عام ڈیبگ حرکت ہے۔ ہر ایک سے JSON ایکسپورٹ کریں، اور فرق دکھاتا ہے کہ کس پروسیسنگ قدم نے فیلڈ چھوڑی یا بدلی۔</p>\n<p><a href=\"/ur/tasveer-ka-size-dekhein/\">Image Dimensions Checker</a> EXIF پڑھنے کے ساتھ اچھی طرح جوڑتا ہے جب سائز سوال ہو۔ ابعاد اور DPI ساتھ طے کرتے ہیں کہ تصویر پرنٹ کے لیے موزوں ہے یا صرف اسکرین کے لیے۔</p>\n<h2 id=\"removing-exif\">EXIF محفوظ طریقے سے ہٹانا</h2>\n<p>EXIF پڑھنا صرف آدھا کام ہے۔ دوسرا نصف اسے ہٹانا ہے اس سے پہلے کہ تصویر کہیں عوامی جائے۔</p>\n<p><a href=\"/ur/tasveer-metadata-hatayein/\">Remove Image Metadata</a> ٹول EXIF، GPS، XMP، IPTC، تبصرے، اور PNG متن چنک آپ کے براؤزر میں مقامی طور پر ہٹاتا ہے۔ کچھ بھی اپ لوڈ نہیں ہوتا۔</p>\n<p>Lossless Binary Strip JPG اور PNG فائلوں پر کام کرتا ہے، میٹا ڈیٹا سیگمنٹ ہٹاتا ہے بغیر ایک پکسل کو ڈی کوڈ یا دوبارہ کمپریس کیے۔ تصویر کوالٹی اچھوتی رہتی ہے۔</p>\n<p>Full Canvas Re-encode تصویر کو اس کے پکسل سے دوبارہ بناتا ہے، جو ضمانت دیتا ہے کہ ہر وراثتی بائنری سیگمنٹ چھوٹ جائے۔ یہ WebP اور HEIC کے لیے خود بخود استعمال ہوتا ہے۔</p>\n<p>صفائی کے بعد نتیجہ تصدیق کریں۔ صاف شدہ فائل کو <a href=\"/ur/tasveer-metadata-dekhein/\">Image Metadata Viewer</a> میں واپس ڈال دیں اور سبز بینر کی تصدیق کریں: کوئی EXIF، GPS، یا چھپا ہوا کیمرہ ٹیگ نہیں۔</p>\n<p>مکمل ہٹانے کی گائیڈ کے لیے <a href=\"/ur/blog/tasveer-metadata-hatayein-rehnumai/\">Remove Image Metadata: Complete Guide</a> پڑھیں، اور ڈیٹا کے پیچھے پرائیویسی خطرات کے لیے <a href=\"/ur/blog/photo-privacy-gps-exif-khatrat/\">Photo Privacy: GPS, EXIF and Metadata Risks</a> پڑھیں۔</p>\n<h2 id=\"exif-myths\">عام EXIF افسانے</h2>\n<p>EXIF کے بارے میں کئی افسانے برقرار ہیں، اور ہر ایک تحفظ کا غلط احساس دیتا ہے۔ انہیں سیدھا درست کرنا قابل قدر ہے۔</p>\n<p>افسانہ ایک: تصویر سائز بدلنے سے اس کا میٹا ڈیٹا ہٹ جاتا ہے۔ سائز بدلنا عام طور پر EXIF رکھتا ہے جب تک ٹول اسے واضح طور پر نہ ہٹائے۔ چھوٹی تصویر وہی GPS نقاط لے کر آ سکتی ہے۔</p>\n<p>افسانہ دو: فارمیٹ بدلنے سے میٹا ڈیٹا ہٹ جاتا ہے۔ JPG کو PNG میں بدلنا EXIF چھوڑ سکتا ہے، مگر یہ اسے eXIf چنک میں لے بھی جا سکتا ہے۔ تبدیلی پر کبھی اندازہ نہ لگائیں۔</p>\n<p>افسانہ تین: کراپ کرنے سے مقام ڈیٹا ہٹ جاتا ہے۔ کراپ پکسل بدلتا ہے، ہیڈر نہیں۔ GPS ٹیگ کراپ سے بچتے ہیں جب تک ٹول انہیں نہ ہٹائے۔</p>\n<p>افسانہ چار: بغیر نظر آنے والے مقام والی تصویر محفوظ ہے۔ مقام ہیڈر میں ہے، تصویر میں نہیں۔ خالی دیوار کی تصویر پھر بھی درست نقاط لے کر آ سکتی ہے۔</p>\n<p>افسانہ پانچ: صرف پیشہ ور افراد کو فکر کرنی چاہیے۔ فون کیمرے پیشہ ور کیمروں جیسا ہی EXIF لکھتے ہیں، بشمول GPS۔ ہر شخص جو تصاویر شیئر کرتا ہے متاثر ہوتا ہے۔</p>\n<h2 id=\"exif-explained-summary\">مختصر ورژن</h2>\n<p>EXIF وہ چھپا ہوا ڈیٹا ہے جو آپ کا کیمرہ ہر تصویر میں لکھتا ہے: آلے کی شناخت، ایکسپوژر سیٹنگ، ٹائم اسٹیمپ، اور GPS نقاط۔ یہ IFD ڈائریکٹریوں میں منظم ہوتا ہے۔</p>\n<p>سوشل ایپس اسے خود بخود ہٹاتی ہیں، مگر مارکیٹ پلیس، فورم، اور ای میل اکثر نہیں ہٹاتے۔ تصاویر کا سیٹ آپ کے معمولات، آپ کی جگہیں، اور آپ کے آلات ظاہر کر سکتا ہے۔</p>\n<p>EXIF کو <a href=\"/ur/tasveer-metadata-dekhein/\">Image Metadata Viewer</a> سے پڑھیں، اسے <a href=\"/ur/tasveer-metadata-hatayein/\">Remove Image Metadata</a> ٹول سے ہٹائیں، اور صاف شدہ فائل کو دوبارہ جانچ کر تصدیق کریں۔ آپ کی تصاویر صرف وہی بتانی چاہیے جو آپ دکھانا چاہتے ہیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کیا EXIF ڈیٹا ہٹانے کے بعد بحال ہو سکتا ہے؟","answer":"نہیں۔ ایک بار فائل سے میٹا ڈیٹا سیگمنٹ ہٹانے کے بعد وہ معلومات اس کاپی سے چلی جاتی ہیں — بحال کرنے کے لیے کچھ باقی نہیں رہتا۔ اسی لیے ہٹانے سے پہلے اپنے لیے اصل کاپی رکھنی چاہیے۔"},{"question":"کیا EXIF ڈیٹا تصویر کوالٹی یا فائل سائز کو متاثر کرتا ہے؟","answer":"EXIF پکسل کی شکل نہیں بدلتا، مگر یہ فائل سائز بڑھاتا ہے۔ کیمرہ تصاویر میں اکثر سرایت شدہ پیش نظارہ تھمب نیل، XMP بلاک، اور تبصرہ سیگمنٹ ہوتے ہیں، جو دسیوں کلو بائٹ بڑھا سکتے ہیں۔ انہیں ہٹانے سے فائل ہلکی ہوتی ہے۔"},{"question":"کیا تمام کیمرے اور فون EXIF ڈیٹا لکھتے ہیں؟","answer":"تقریباً تمام ڈیجیٹل کیمرے اور اسمارٹ فون ڈیفالٹ سے EXIF ڈیٹا لکھتے ہیں، بشمول بنانے والا، ماڈل، ایکسپوژر سیٹنگ، اور ٹائم اسٹیمپ۔ GPS نقاط مقام خدمات فعال ہونے پر منحصر ہوتے ہیں۔ کچھ کیمرے آپ کو GPS بند کرنے دیتے ہیں۔"},{"question":"کیا EXIF ڈیٹا ثابت کر سکتا ہے کہ تصویر کب اور کہاں لی گئی؟","answer":"EXIF ٹائم اسٹیمپ اور GPS نقاط ثبوت ہیں، مگر حتمی ثبوت نہیں۔ ٹائم اسٹیمپ ایڈٹ ہو سکتے ہیں، GPS ڈیٹا جعلی ہو سکتا ہے، اور ہٹائی گئی فائل کچھ بھی نہیں لے کر آتی۔ قانونی یا صحافتی مقاصد کے لیے EXIF کو دوسرے ثبوت کی حمایت چاہیے ہوتی ہے۔"},{"question":"ایک ہی تصویر کی دو کاپیاں مختلف EXIF ڈیٹا کیوں دکھاتی ہیں؟","answer":"ہر کاپی مختلف پروسیسنگ سے گزری۔ ایک سوشل ایپ سے گزری ہو سکتی ہے جس نے سب کچھ ہٹا دیا، جبکہ دوسری اصل رہی۔ ایڈیٹنگ، تبدیلی، اور دوبارہ ایکسپورٹ ہر ایک فیلڈ بڑھا، بدل، یا ہٹا سکتا ہے۔"},{"question":"کیا EXIF ڈیٹا تصویر واٹر مارک جیسا ہے؟","answer":"نہیں۔ واٹر مارک پکسل میں نظر آتا ہے — تصویر پر لوگو یا متن۔ EXIF پوشیدہ ہیڈر ڈیٹا ہے جو تصویر کو بیان کرتا ہے۔ واٹر مارک اسکرین شاٹ اور دوبارہ محفوظ کرنے سے بچتا ہے؛ EXIF نہیں بچتا۔"}];
